/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { StringManager } from "../../src/i18n/StringManager.js";
import { LengthContractionScreen } from "../../src/length-contraction/LengthContractionScreen.js";
import { LightClockScreen } from "../../src/light-clock/LightClockScreen.js";
import { SpecialRelativityPreferencesModel } from "../../src/preferences/SpecialRelativityPreferencesModel.js";
import { RelativisticDopplerScreen } from "../../src/relativistic-doppler/RelativisticDopplerScreen.js";
import SpecialRelativityColors from "../../src/SpecialRelativityColors.js";
import { SpacetimeDiagramScreen } from "../../src/spacetime/SpacetimeDiagramScreen.js";
import { TwinParadoxScreen } from "../../src/twin-paradox/TwinParadoxScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from specialRelativityQueryParameters.
  const simPreferences = new SpecialRelativityPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new LightClockScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().lightClockStringProperty,
      tandem: Tandem.ROOT.createTandem("lightClockScreen"),
      backgroundColorProperty: SpecialRelativityColors.backgroundColorProperty,
    }),
    new SpacetimeDiagramScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().spacetimeStringProperty,
      tandem: Tandem.ROOT.createTandem("spacetimeScreen"),
      backgroundColorProperty: SpecialRelativityColors.backgroundColorProperty,
    }),
    // Third of five: the ladder-and-barn puzzle is resolved by relativity of
    // simultaneity, so it follows the screen that introduces it.
    new LengthContractionScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().lengthContractionStringProperty,
      tandem: Tandem.ROOT.createTandem("lengthContractionScreen"),
      backgroundColorProperty: SpecialRelativityColors.backgroundColorProperty,
    }),
    new TwinParadoxScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().twinParadoxStringProperty,
      tandem: Tandem.ROOT.createTandem("twinParadoxScreen"),
      backgroundColorProperty: SpecialRelativityColors.backgroundColorProperty,
    }),
    new RelativisticDopplerScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().relativisticDopplerStringProperty,
      tandem: Tandem.ROOT.createTandem("relativisticDopplerScreen"),
      backgroundColorProperty: SpecialRelativityColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { SpecialRelativityColors, stringManager, simPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
